const isPaymentOpen = (payment) => payment && (payment.status === "pending" || payment.status === "scanned");
let _paddleScriptPromise = null;
function loadPaddle(mode) {
  if (typeof window === "undefined") return Promise.reject(new Error("Paddle requires a browser"));
  if (_paddleScriptPromise) return _paddleScriptPromise;
  _paddleScriptPromise = new Promise((resolve, reject) => {
    if (window.Paddle) { window.Paddle.Environment.set(mode === "sandbox" ? "sandbox" : "production"); resolve(window.Paddle); return; }
    const script = document.createElement("script");
    script.src = "https://cdn.paddle.com/paddle/v2/paddle.js";
    script.onload = () => { window.Paddle.Environment.set(mode === "sandbox" ? "sandbox" : "production"); resolve(window.Paddle); };
    script.onerror = () => { _paddleScriptPromise = null; reject(new Error("Could not load Paddle checkout")); };
    document.head.appendChild(script);
  });
  return _paddleScriptPromise;
}

