function mapApiProduct(product, index = 0) {  const stock = product.on_hand ?? 0;  return {    ...product,    id: product.id,    name: product.name,    category: product.category?.name || "Uncategorized",    price: Number(product.price),    stock,    sku: product.sku,    status: stock < (product.reorder_point ?? 10) ? "Low stock" : "In stock",    image: product.image || null,    color: PRODUCT_COLORS[index % PRODUCT_COLORS.length],    letter: product.name.slice(0, 2).toUpperCase(),    categoryId: product.category_id,  };}

function Sidebar({ active, onNavigate, open, onClose, onSignOut, workspace, user, activeMembershipRole }) {  return <><div className={`fixed inset-0 z-30 bg-[#17181c]/35 transition md:hidden ${open ? "visible opacity-100" : "invisible opacity-0"}`} onClick={onClose} /><aside className={`fixed inset-y-0 left-0 z-40 flex w-[252px] flex-col bg-[#17181c] px-3.5 py-5 text-white transition-transform duration-300 md:static md:z-auto md:translate-x-0 ${open ? "translate-x-0" : "-translate-x-full"}`}><div className="flex items-center justify-between px-3"><Logo light /><IconButton label="Close menu" onClick={onClose} className="text-[#898a94] hover:bg-[#292a30] hover:text-white md:hidden"><X size={17} /></IconButton></div><div className="mt-9 px-2"><p className="mb-2 px-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#686970]">Workspace</p><nav className="space-y-1">{NAV_ITEMS.filter((item) => canViewRole(activeMembershipRole, item.id)).map(({ id, label, icon: Icon }) => <SidebarLink key={id} label={label} icon={Icon} active={active === id} onClick={() => { onNavigate(id); onClose(); }} />)}</nav></div><div className="mt-7 px-2"><p className="mb-2 px-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#686970]">Manage</p><nav className="space-y-1">{WORKSPACE_ITEMS.filter((item) => canViewRole(activeMembershipRole, item.id)).map(({ id, label, icon: Icon }) => <SidebarLink key={id} label={label} icon={Icon} active={active === id} onClick={() => { onNavigate(id); onClose(); }} />)}</nav></div><div className="mt-auto"><div className="mb-3 rounded-xl border border-[#33343a] bg-[#202126] p-3"><div className="flex items-center justify-between"><div className="flex items-center gap-2"><div className="flex h-7 w-7 items-center justify-center rounded-lg bg-[#c4f27c] text-[10px] font-extrabold text-[#1d2817]">{workspace?.company?.name?.slice(0, 2).toUpperCase() || "CS"}</div><div><p className="text-[11px] font-bold">{workspace?.company?.name || "Cedar & Stone"}</p><p className="mt-0.5 flex items-center gap-1 text-[9px] text-[#85868e]"><span className="h-1.5 w-1.5 rounded-full bg-[#7cc551]" /> {workspace?.store?.name || "Main store"}</p></div></div><ChevronDown size={13} className="text-[#777880]" /></div><div className="mt-3 flex items-center justify-between border-t border-[#35363c] pt-3"><span className="text-[9px] text-[#7e7f88]">{(workspace?.subscription?.plan_code || "starter") + (workspace?.subscription?.status === "pending" ? " · pending" : "")} plan</span><button onClick={() => onNavigate("billing")} className="text-[9px] font-bold text-[#c4f27c]">Manage</button></div></div><div className="flex items-center gap-2 px-2"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-[#d7c0a2] text-[10px] font-bold text-[#4c3b2d]">{user?.full_name?.slice(0, 2).toUpperCase() || "NS"}</div><div className="min-w-0 flex-1"><p className="truncate text-[11px] font-bold">{user?.full_name || "Nadia Sok"}</p><p className="text-[9px] text-[#777880]">{activeMembershipRole || "Owner"}</p></div><IconButton label="Sign out" onClick={onSignOut} className="text-[#777880] hover:bg-[#292a30] hover:text-white"><LogOut size={15} /></IconButton></div></div></aside></>;}

