function AppHeader({ title, subtitle, onMenu, onSearch, onNotify, onHelp, onOpenNotifications, unreadCount = 0, children, workspace, stores = [], onSwitchStore, onAddStore, onOpenAdmin, onNavigate }) {  const { theme, toggleTheme } = useTheme();  return <header className="flex min-h-[74px] items-center justify-between gap-3 border-b border-[#e9e9ef] bg-[#fafafd]/90 px-5 backdrop-blur dark:border-[#2a2b30] dark:bg-[#1a1b1f]/90 lg:px-8"><div className="flex min-w-0 items-center gap-3"><IconButton label="Open menu" onClick={onMenu} className="md:hidden"><Menu size={19} /></IconButton><div className="min-w-0"><h1 className="truncate text-[18px] font-extrabold tracking-[-.04em] text-[#202128] dark:text-[#e4e4e8]">{title}</h1>{subtitle && <p className="mt-0.5 hidden text-[11px] text-[#92939d] dark:text-[#6b6c76] sm:block">{subtitle}</p>}</div></div><div className="flex min-w-0 items-center gap-1 sm:gap-2">{onOpenAdmin && <Button variant="soft" size="xs" onClick={onOpenAdmin}><ShieldCheck size={13} /> Admin</Button>}<div className="hidden min-w-0 items-center gap-2 rounded-xl border border-[#e6e6ed] bg-white px-3 text-[#62636d] dark:border-[#363740] dark:bg-[#1f2025] dark:text-[#9a9aa4] sm:flex"><Store size={14} className="shrink-0 text-[#6957f5]" /><Dropdown value={workspace?.store?.id || ""} onChange={(v) => onSwitchStore?.(v)} placeholder="Select store" triggerClass="h-9 max-w-[132px] bg-transparent text-[11px] font-bold text-[#62636d] dark:text-[#9a9aa4]" options={stores.map((store) => ({ value: String(store.id), label: store.name }))} />{onAddStore && <button aria-label="Add store" title="Add store" onClick={onAddStore} className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-[#92939d] hover:bg-[#f0efff] hover:text-[#6957f5] dark:hover:bg-[#2a2b32] dark:hover:text-[#8b7cf7]"><Plus size={13} /></button>}</div><div className="hidden items-center gap-2 rounded-xl border border-[#e6e6ed] bg-white px-3 text-[#a0a1aa] dark:border-[#363740] dark:bg-[#1f2025] dark:text-[#6b6c76] lg:flex"><Search size={15} /><input onChange={onSearch} placeholder="Search anything..." className="h-9 w-[125px] bg-transparent text-xs text-[#292a31] outline-none placeholder:text-[#a0a1aa] dark:text-[#d0d0d5] dark:placeholder:text-[#6b6c76]" /></div><IconButton label="Search" onClick={onSearch} className="lg:hidden"><Search size={17} /></IconButton><IconButton label="Help" onClick={onHelp}><CircleHelp size={17} /></IconButton><button aria-label="Toggle dark mode" title={theme === "dark" ? "Switch to light mode" : "Switch to dark mode"} onClick={toggleTheme} className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-lg text-[#70717a] transition hover:bg-[#f0f0f5] hover:text-[#272831] dark:text-[#9a9aa4] dark:hover:bg-[#2a2b32] dark:hover:text-[#e4e4e8]">{theme === "dark" ? <SunMedium size={17} /> : <Moon size={17} />}</button><button aria-label="Notifications" onClick={onOpenNotifications || onNotify} className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-lg text-[#70717a] transition hover:bg-[#f0f0f5] hover:text-[#272831] dark:text-[#9a9aa4] dark:hover:bg-[#2a2b32] dark:hover:text-[#e4e4e8]"><Bell size={17} />{unreadCount > 0 && <span className="absolute right-1 top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-[#6957f5] px-1 text-[9px] font-extrabold text-white">{unreadCount}</span>}</button>{children}</div></header>;}

function AppShell({ active, onNavigate, children, onSignOut, toast, onMenu, mobileMenu, onCloseMenu, onNotify, onHelp, onOpenNotifications, unreadCount = 0, workspace, user, stores, onSwitchStore, onAddStore, onOpenAdmin }) {  return <div className="flex h-screen overflow-hidden bg-[#fafafd] text-[#202128]"><Sidebar active={active} onNavigate={onNavigate} open={mobileMenu} onClose={onCloseMenu} onSignOut={onSignOut} workspace={workspace} user={user} activeMembershipRole={workspace?.membership_role} /><div className="flex min-w-0 flex-1 flex-col"><AppHeader title={pageMeta[active]?.title || "Overview"} subtitle={pageMeta[active]?.subtitle} onMenu={onMenu} onNotify={onNotify} onHelp={onHelp} onOpenNotifications={onOpenNotifications} unreadCount={unreadCount} workspace={workspace} stores={stores} onSwitchStore={onSwitchStore} onAddStore={onAddStore} onOpenAdmin={onOpenAdmin} onNavigate={onNavigate}>{active === "pos" && <Badge tone="green" dot>Online</Badge>}</AppHeader><main className="app-scrollbar flex-1 overflow-y-auto">{children}</main></div>{toast && <div className="fixed bottom-5 right-5 z-50 flex max-w-[calc(100vw-40px)] items-center gap-2 rounded-xl bg-[#17181c] px-4 py-3 text-xs font-semibold text-white shadow-panel animate-fade-up"><CheckCircle2 size={15} className="text-[#c4f27c]" />{toast}</div>}</div>;}

